1	// The sheepdog pack's fleet CONFIG reader — the one parser for the enforcer repo's
2	// `sheepdog` pack entry.
3	//
4	// It lives at the pack root, not inside a task, because BOTH sweeps read the same
5	// entry: the census (tasks/fleet-census/) needs `owner` and `exclude`, the freshness
6	// sweep (tasks/fleet-freshness/) needs those plus `canonRepo` and `staleDays`. A
7	// second reader would be a second place for the owner/exclude semantics to drift —
8	// and this is what the file-placement skill calls lifting a shared dependency to the
9	// nearest common ancestor: distance 2 from each task instead of one task reaching
10	// into the other's folder.
11	
12	// The sheepdog repo's .claudinite-checks.json carries, on its sheepdog pack entry:
13	//   { "id": "sheepdog", "config": { owner: "missingbulb", kind: "user", exclude: ["owner/repo", ...],
14	//                                   canonRepo: "missingbulb/Claudinite", staleDays: 14 } }
15	// owner is who to cover (default: the sheepdog repo's own owner); exclude is the repos
16	// deliberately kept out (a full owner/name each, lowercased). canonRepo and staleDays
17	// are the freshness sweep's two knobs and both default, so an existing config keeps
18	// working untouched. Callers read the home repo's file raw (fetched over the API, no
19	// engine on hand), so this resolves the entry itself — legacy top-level
20	// packConfig.sheepdog stays readable underneath until the `pack-entry-config` baseline
21	// migration retires (drop the fallback then). A missing config is an unreadable
22	// config: throw — absence is not consent to cover everything.
23	export function parseSheepdogConfig(cfg, home) {
24	  const entry = (Array.isArray(cfg?.packs) ? cfg.packs : []).find((e) => e?.id === 'sheepdog');
25	  const sd = entry?.config ?? cfg?.packConfig?.sheepdog;
26	  if (!sd || typeof sd !== 'object') {
27	    throw new Error(`the sheepdog repo ${home} declares no sheepdog config { owner, exclude } (on the pack entry or legacy packConfig.sheepdog) — nothing to cover`);
28	  }
29	  const owner = String(sd.owner ?? home.split('/')[0]).toLowerCase();
30	  const exclude = new Set((Array.isArray(sd.exclude) ? sd.exclude : []).map((s) => String(s).toLowerCase()));
31	  // Claudinite's own repo — what a member's stamped ref is measured against. Named
32	  // rather than inferred from the ref, because a ref tells you nothing about where
33	  // it came from; defaulted so no existing sheepdog config has to change.
34	  const canonRepo = String(sd.canonRepo ?? `${owner}/Claudinite`);
35	  // How far behind is too far. Not a hard number in code: a fleet whose members
36	  // legitimately go quiet for longer raises it rather than living with false alarms.
37	  const raw = Number(sd.staleDays);
38	  const staleDays = Number.isFinite(raw) && raw > 0 ? raw : 14;
39	  return { owner, exclude, canonRepo, staleDays };
40	}
