1	#!/usr/bin/env node
2	// The sheepdog pack's fleet-coverage CENSUS — the cross-repo reach the pack adds.
3	// Run by this pack's `fleet-census` scheduled task (tasks/fleet-census/), whose
4	// worker calls `main()` below as the task's `prework` — Action-side
5	// inside the repo's scheduler workflow, where the FLEET_GITHUB_TOKEN the task
6	// declares in `required_secrets` is reachable as ordinary environment. Still
7	// runnable by hand (`node check-fleet-coverage.mjs`) via the CLI guard at the foot.
8	//
9	// Its concern is COVERAGE ALONE — one thing: reads the fleet config from the
10	// sheepdog (home) repo's sheepdog pack-entry config (owner to cover + exclude list),
11	// enumerates every repo under that owner, classifies each (covered / uncovered /
12	// excluded / skipped fork-or-archived), publishes the picture to the run summary,
13	// and converges one adoption issue per actionable uncovered repo in the home repo
14	// (open while uncovered, closed once covered or excluded). That issue is its ENTIRE
15	// effect on an uncovered repo — the census never writes to one, and nothing downstream
16	// adopts it either: the owner reads the issue and chooses to adopt Claudinite or to
17	// ignore it. It does NOT build the
18	// work plan (that is each repo's own scheduler's job, engine/scheduler/run.mjs) and it does
19	// NOT touch migrations: application and retirement are the migrations flow's own
20	// standalone passes (migrations/fleet-apply.mjs + migrations/fleet-retire.mjs, run
21	// by the daily routine) — the census is a coverage audit, not a migrations helper.
22	//
23	// Two rules kept deliberately:
24	//   - a marker check that ERRORS makes the repo UNKNOWN, never uncovered — no
25	//     issue is opened for it and the run fails so the error escalates;
26	//   - an unreadable/absent sheepdog config aborts the census — absence is
27	//     not consent to cover everything with no exclusions.
28	//
29	// Dependency-free (global fetch, Node 20+); read-only toward every repo except the
30	// home repo, where it writes the adoption issues + label.
31	// It lives IN its task's folder (tasks/fleet-census/) because nothing else uses it —
32	// only this task's worker.mjs imports it. What IS shared with the freshness sweep sits
33	// at the pack root: the cross-repo REST primitives (fleet-api.mjs) and the config
34	// reader (fleet-config.mjs).
35	
36	import { appendFileSync } from 'node:fs';
37	import { pathToFileURL } from 'node:url';
38	import { makeGh, paged, isCovered, ensureLabel, labeledIssues } from '../../fleet-api.mjs';
39	import { parseSheepdogConfig } from '../../fleet-config.mjs';
40	
41	const LABEL = 'fleet-adoption';
42	const adoptionTitle = (fullName) => `Adopt ${fullName} into the Claudinite fleet`;
43	const TITLE_RE = /^Adopt (\S+\/\S+) into the Claudinite fleet$/;
44	
45	function adoptionBody(fullName) {
46	  return [
47	    `\`${fullName}\` exists under this account but does not mount Claudinite (no tracked`,
48	    '`.claudinite/` signal on its default branch) and is not on the exclude list.',
49	    '',
50	    'Pick one:',
51	    '',
52	    '- **Adopt it** — run the adoption in a session on that repo (ask for "adopt Claudinite";',
53	    '  the `adopt-claudinite` skill drives `bootstrap.md`). This is a human-initiated step by',
54	    '  design: adoption is the one thing a repo cannot do for itself, because the scheduler',
55	    '  that would run it is what adoption installs. Nothing will do it on your behalf.',
56	    `- **Keep it out** — add \`${fullName}\` to the sheepdog pack entry's \`config.exclude\` in this`,
57	    '  (sheepdog) repo\'s `.claudinite-checks.json`, with a reason.',
58	    '',
59	    'This issue is converged by the daily fleet-census task: it closes itself once the',
60	    'repo is covered (`completed`) or opted out (`not planned`), and a close without either',
61	    'gets reopened while the repo stays uncovered.',
62	  ].join('\n');
63	}
64	
65	// --- adoption-issue convergence ----------------------------------------------
66	
67	async function convergeIssues(gh, home, { uncovered, coveredSet, optedOutSet }) {
68	  const actions = [];
69	  const { open: openIssues, closed } = await labeledIssues(gh, home, LABEL);
70	  const open = new Map(openIssues.map((i) => [i.title, i]));
71	
72	  for (const fullName of uncovered) {
73	    const title = adoptionTitle(fullName);
74	    if (open.has(title)) continue;
75	    const prior = closed.filter((i) => i.title === title)
76	      .sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at))[0];
77	    if (prior && prior.state_reason === 'not_planned') continue; // owner declined; opt-out is the standing fix
78	    if (prior) {
79	      await gh(`/repos/${home}/issues/${prior.number}`, { method: 'PATCH', body: { state: 'open' } });
80	      await gh(`/repos/${home}/issues/${prior.number}/comments`, {
81	        method: 'POST', body: { body: `Reopened by the census: \`${fullName}\` is still uncovered.` },
82	      });
83	      actions.push(`reopened #${prior.number} (${fullName})`);
84	    } else {
85	      const { status, json } = await gh(`/repos/${home}/issues`, {
86	        method: 'POST',
87	        body: { title, body: adoptionBody(fullName), labels: [LABEL] },
88	      });
89	      if (status !== 201) throw new Error(`creating adoption issue for ${fullName} returned ${status}`);
90	      actions.push(`opened #${json.number} (${fullName})`);
91	    }
92	  }
93	
94	  for (const [title, issue] of open) {
95	    const m = TITLE_RE.exec(title);
96	    if (!m) continue;
97	    const fullName = m[1].toLowerCase();
98	    let reason = null; let note = null;
99	    if (coveredSet.has(fullName)) {
100	      reason = 'completed'; note = 'now mounts Claudinite — covered';
101	    } else if (optedOutSet.has(fullName)) {
102	      reason = 'not_planned'; note = "on the exclude list (the sheepdog pack entry's config.exclude)";
103	    } else if (!uncovered.includes(fullName)) {
104	      reason = 'not_planned'; note = 'no longer an adoption candidate (deleted, archived, transferred, or now a fork)';
105	    }
106	    if (!reason) continue;
107	    await gh(`/repos/${home}/issues/${issue.number}/comments`, {
108	      method: 'POST', body: { body: `Closed by the census: \`${m[1]}\` ${note}.` },
109	    });
110	    await gh(`/repos/${home}/issues/${issue.number}`, {
111	      method: 'PATCH', body: { state: 'closed', state_reason: reason },
112	    });
113	    actions.push(`closed #${issue.number} (${m[1]}: ${note})`);
114	  }
115	  return actions;
116	}
117	
118	// --- main --------------------------------------------------------------------
119	
120	// Exported so the fleet-census task's worker can invoke the census in-process
121	// rather than reimplementing it; the CLI guard below keeps the standalone run.
122	export async function main() {
123	  const token = process.env.FLEET_GITHUB_TOKEN;
124	  const home = process.env.GITHUB_REPOSITORY;
125	  if (!token) {
126	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
127	      + '(this account, ALL repositories, Metadata read, Contents read + Issues read/write) — '
128	      + 'the default GITHUB_TOKEN sees only this repo and cannot take a fleet census.');
129	  }
130	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
131	  const gh = makeGh(token);
132	
133	  // Read the fleet config from this (sheepdog) repo's sheepdog pack entry.
134	  const cfgRes = await gh(`/repos/${home}/contents/.claudinite-checks.json`);
135	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
136	    throw new Error(`the sheepdog repo ${home} has no readable .claudinite-checks.json (status ${cfgRes.status})`);
137	  }
138	  let cfg;
139	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
140	    throw new Error(`unparsable .claudinite-checks.json on ${home}: ${e.message}`);
141	  }
142	  const { owner, exclude: optOut } = parseSheepdogConfig(cfg, home);
143	
144	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
145	    .filter((r) => r.owner.login.toLowerCase() === owner);
146	  if (mine.length === 0) {
147	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope; `
148	      + 'refusing to run a census that would close every adoption issue as stale');
149	  }
150	
151	  const covered = []; const uncovered = []; const optedOut = []; const skipped = []; const unknown = [];
152	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
153	    const fullName = r.full_name.toLowerCase();
154	    if (fullName === home.toLowerCase()) continue; // the canon doesn't mount itself
155	    if (r.archived || r.fork) { skipped.push(`${r.full_name} (${r.archived ? 'archived' : 'fork'})`); continue; }
156	    let isCov;
157	    try {
158	      isCov = await isCovered(gh, r.full_name);
159	    } catch (e) {
160	      unknown.push(`${r.full_name} — ${e.message}`);
161	      continue;
162	    }
163	    if (isCov) covered.push(fullName);
164	    else if (optOut.has(fullName)) optedOut.push(fullName);
165	    else uncovered.push(fullName);
166	  }
167	
168	  await ensureLabel(gh, home, LABEL, { color: '1D76DB', description: 'Repo awaiting adoption into the Claudinite fleet' });
169	  const actions = await convergeIssues(gh, home, {
170	    uncovered, coveredSet: new Set(covered), optedOutSet: new Set(optedOut),
171	  });
172	
173	  const summary = [
174	    `# Fleet coverage census — ${owner}`,
175	    '',
176	    `| covered | uncovered | opted out | skipped (fork/archived) | unknown |`,
177	    `| --- | --- | --- | --- | --- |`,
178	    `| ${covered.length} | ${uncovered.length} | ${optedOut.length} | ${skipped.length} | ${unknown.length} |`,
179	    '',
180	    uncovered.length ? `**Uncovered (adoption issue open):** ${uncovered.join(', ')}` : '**Uncovered:** none 🎉',
181	    optedOut.length ? `**Opted out:** ${optedOut.join(', ')}` : '',
182	    skipped.length ? `**Skipped:** ${skipped.join(', ')}` : '',
183	    unknown.length ? `**UNKNOWN (marker check errored — fix the token/scope):** ${unknown.join('; ')}` : '',
184	    actions.length ? `**Issue actions:** ${actions.join('; ')}` : '**Issue actions:** none (converged)',
185	  ].filter(Boolean).join('\n');
186	
187	  console.log(summary);
188	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
189	
190	  if (unknown.length) {
191	    throw new Error(`${unknown.length} repo(s) could not be classified — unknown is not uncovered, `
192	      + 'no adoption issues were opened for them, and this run fails so the cause is escalated');
193	  }
194	}
195	
196	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
197	if (isMain) {
198	  main().catch((e) => { console.error(`fleet-coverage census failed: ${e.message}`); process.exit(1); });
199	}
