1	#!/usr/bin/env node
2	// The sheepdog pack's fleet-FRESHNESS sweep — the second half of the enforcer's job.
3	// Run by this pack's `fleet-freshness` scheduled task (tasks/fleet-freshness/), whose
4	// worker calls `main()` below as the task's `prework`, Action-side inside
5	// the enforcer repo's scheduler workflow where FLEET_GITHUB_TOKEN is reachable. Still
6	// runnable by hand (`node check-fleet-freshness.mjs`) via the CLI guard at the foot.
7	//
8	// WHY IT EXISTS. Under per-project scheduling every member maintains ITSELF: its own
9	// vendored `claudinite-scheduler.yml` fires hourly, and its `baselining` task re-vendors
10	// the mount from canon. That is the right architecture — and it removed the last thing
11	// that ever looked at a member from the outside. A member whose scheduler was never
12	// vendored, whose workflow was deleted, or whose baselining has been failing for a
13	// fortnight is now invisible: it is `covered` to the census (it still carries a
14	// declaration), it files no failure issue (nothing runs to fail), and it silently drifts.
15	// Self-maintenance cannot detect its own absence. This sweep is the outside look.
16	//
17	// ITS CONCERN IS FRESHNESS ALONE — is each COVERED member actually keeping up? The
18	// census (check-fleet-coverage.mjs) asks the prior question, whether a repo is covered
19	// at all, and opens adoption issues; this one takes coverage as given and asks whether
20	// coverage is still MEANING anything. An uncovered repo is skipped here, not
21	// double-reported — and so is a member that declares itself DORMANT: its scheduler
22	// stops before it evaluates anything, so its mount falls behind by design, and every
23	// classification below would report a repo for obeying its own declaration.
24	//
25	// The classification is deliberately about ROOT CAUSE, in precedence order:
26	//   no-stamp        declares packs but was never vendored — no engine on disk at all
27	//   no-scheduler    no vendored scheduler workflow — it has no cron, so it will
28	//                   never baseline itself, and every other symptom follows from this
29	//   ref-not-on-trunk  the stamped ref is not an ancestor of canon's default branch
30	//                   (or is not a canon commit at all) — vendoring's #328 anti-rewind
31	//                   guard refuses to write over it, so the repo is WEDGED, not merely late
32	//   behind          on trunk, but the commit it is stamped at is older than staleDays
33	//                   while canon has moved on — baselining has stopped landing
34	//
35	// THE ONE ASSUMPTION, stated plainly: baselining reverts a stamp-only bump, so
36	// `claudinite.updated` advances only when canon actually changed that member's vendor
37	// set. Age of the STAMPED REF is therefore the honest liveness measure, and `behind`
38	// reads "this member has not picked canon up in staleDays" — not "canon moved". It can
39	// still misfire on a member whose vendor set genuinely saw no change in that window;
40	// `staleDays` (default 14) is the knob, and the issue body says so.
41	//
42	// Same two rules the census keeps: an indeterminate repo is UNKNOWN, never a finding —
43	// no issue is opened for it and the run fails so the cause escalates; and an unreadable
44	// config aborts rather than silently sweeping a fleet it cannot scope.
45	//
46	// Dependency-free (global fetch, Node 20+); read-only toward every member, and writes
47	// only the enforcer repo's own drift issues + label.
48	//
49	// It lives IN its task's folder (tasks/fleet-freshness/) because nothing else uses it —
50	// only this task's worker.mjs imports it. What IS shared with the census sits at the
51	// pack root: the cross-repo REST primitives (fleet-api.mjs) and the config reader
52	// (fleet-config.mjs).
53	
54	import { appendFileSync } from 'node:fs';
55	import { pathToFileURL } from 'node:url';
56	import { makeGh, paged, ensureLabel, labeledIssues, readDeclaration, isDormant, DECLARATION } from '../../fleet-api.mjs';
57	import { parseSheepdogConfig } from '../../fleet-config.mjs';
58	
59	const LABEL = 'fleet-drift';
60	const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';
61	
62	export const FRESH = 'fresh';
63	const driftTitle = (fullName) => `Claudinite mount has fallen behind on ${fullName}`;
64	const TITLE_RE = /^Claudinite mount has fallen behind on (\S+\/\S+)$/;
65	// A machine-readable state marker in the body: it lets a later run notice that the
66	// ROOT CAUSE changed (a repo that was `behind` is now `no-scheduler`) and say so,
67	// without any cross-run state to keep — the issue carries its own last verdict.
68	const marker = (state) => `<!-- fleet-freshness: ${state} -->`;
69	const MARKER_RE = /<!-- fleet-freshness: ([a-z-]+) -->/;
70	
71	// --- classification (pure) ----------------------------------------------------
72	
73	// `compare` is what canon's compare endpoint said about `stampedRef → canon default
74	// branch`, normalized to { status, aheadBy, baseDateMs }, or null when the ref is not
75	// a commit in canon at all. Kept free of I/O so every branch is testable directly.
76	export function classifyFreshness({ stampedRef, hasScheduler, compare, nowMs, staleDays }) {
77	  if (!stampedRef) {
78	    return { state: 'no-stamp', detail: `${DECLARATION} carries no claudinite.ref — the repo declares packs but has never been vendored` };
79	  }
80	  if (!hasScheduler) {
81	    return { state: 'no-scheduler', detail: `no ${SCHEDULER} — the repo has no cron, so nothing there will ever baseline it` };
82	  }
83	  if (compare === null) {
84	    return { state: 'ref-not-on-trunk', detail: `the stamped ref ${stampedRef} is not a commit in canon` };
85	  }
86	  // base=stampedRef, head=canon default branch. An ancestor reads `identical` or
87	  // `ahead`; `behind`/`diverged` means the stamp points off trunk (a force-push, a
88	  // ref vendored from a branch), which is exactly what the #328 guard refuses.
89	  if (compare.status !== 'identical' && compare.status !== 'ahead') {
90	    return { state: 'ref-not-on-trunk', detail: `the stamped ref ${stampedRef} is not an ancestor of canon's default branch (compare says "${compare.status}")` };
91	  }
92	  const ageDays = (nowMs - compare.baseDateMs) / 86_400_000;
93	  if (compare.aheadBy > 0 && ageDays > staleDays) {
94	    return {
95	      state: 'behind',
96	      detail: `stamped at ${stampedRef} (${Math.floor(ageDays)} days old), ${compare.aheadBy} canon commit(s) behind — over the ${staleDays}-day window`,
97	    };
98	  }
99	  return { state: FRESH, detail: compare.aheadBy > 0 ? `${compare.aheadBy} canon commit(s) behind, within the ${staleDays}-day window` : 'at canon head' };
100	}
101	
102	// --- issue bodies -------------------------------------------------------------
103	
104	const FIXES = {
105	  'no-stamp': [
106	    'Run the adoption flow against the repo (the `adopt-claudinite` skill) — it vendors the',
107	    'mount and writes the first stamp. Until then the declaration names packs whose code is',
108	    'not present, so nothing Claudinite defines actually runs there.',
109	  ],
110	  'no-scheduler': [
111	    'The repo never cut over to per-project scheduling. Vendor the scheduler',
112	    '(`vendoring/apply-vendor-set.mjs` writes it, with this repo\'s hashed cron minute) and',
113	    'confirm the workflow is enabled in the Actions tab — a repo with no cron runs no task',
114	    'at all, so every other symptom is downstream of this one.',
115	  ],
116	  'ref-not-on-trunk': [
117	    'This is a WEDGE, not a delay: `apply-vendor-set.mjs` refuses to write when the prior',
118	    'stamped ref is not an ancestor of canon HEAD (#328, the anti-rewind guard), so',
119	    'baselining fails on every run and will keep failing. Check whether canon was',
120	    'force-pushed or the mount was vendored from a branch, then re-stamp the repo at a',
121	    'commit that IS on the default branch.',
122	  ],
123	  behind: [
124	    'The scheduler workflow exists but its baselining is not landing. Check the repo\'s',
125	    'recent `Claudinite scheduler` runs: a disabled workflow (GitHub disables cron on repos',
126	    'with no activity for 60 days), a failing baselining task, or a maintenance PR that',
127	    'never merges all look like this.',
128	    '',
129	    'If instead this member\'s vendor set legitimately saw no change in the window, the',
130	    'window is wrong, not the repo — raise `staleDays` on the sheepdog pack entry\'s config.',
131	  ],
132	};
133	
134	function driftBody(fullName, { state, detail }, staleDays) {
135	  return [
136	    marker(state),
137	    `\`${fullName}\` is covered — it carries a tracked \`${DECLARATION}\` — but it is not keeping up with canon.`,
138	    '',
139	    `**What the sweep found (${state}):** ${detail}`,
140	    '',
141	    '**What to do**',
142	    '',
143	    ...FIXES[state],
144	    '',
145	    `This issue is converged by the weekly fleet-freshness task (window: ${staleDays} days): it closes`,
146	    'itself `completed` once the repo is fresh again, and `not planned` once the repo leaves the',
147	    'fleet (excluded, deleted, archived, or no longer covered). A close without either gets',
148	    'reopened while the repo stays behind.',
149	  ].join('\n');
150	}
151	
152	// --- convergence --------------------------------------------------------------
153	
154	// One issue per unhealthy member, keyed by a title that names only the repo — so the
155	// root cause can change without orphaning the thread. Deliberately quieter than the
156	// census on the way in: an already-open issue gets a comment ONLY when the state
157	// actually changed, because a weekly sweep over a fleet that is slow to heal would
158	// otherwise turn every thread into a wall of identical notes.
159	export async function convergeDrift(gh, home, { unhealthy, healthySet, goneSet, dormantSet = new Set(), staleDays }) {
160	  const actions = [];
161	  const { open: openIssues, closed } = await labeledIssues(gh, home, LABEL);
162	  const open = new Map(openIssues.map((i) => [i.title, i]));
163	  const wanted = new Map(unhealthy.map((u) => [u.fullName, u]));
164	
165	  for (const [fullName, verdict] of wanted) {
166	    const title = driftTitle(fullName);
167	    const existing = open.get(title);
168	    if (existing) {
169	      const was = MARKER_RE.exec(existing.body ?? '')?.[1];
170	      if (was === verdict.state) continue; // same story as last week — say nothing
171	      await gh(`/repos/${home}/issues/${existing.number}`, {
172	        method: 'PATCH', body: { body: driftBody(fullName, verdict, staleDays) },
173	      });
174	      await gh(`/repos/${home}/issues/${existing.number}/comments`, {
175	        method: 'POST', body: { body: `The sweep's verdict changed: \`${was ?? 'unrecorded'}\` → \`${verdict.state}\`. ${verdict.detail}.` },
176	      });
177	      actions.push(`updated #${existing.number} (${fullName}: ${was ?? 'unrecorded'} → ${verdict.state})`);
178	      continue;
179	    }
180	    const prior = closed.filter((i) => i.title === title)
181	      .sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at))[0];
182	    if (prior && prior.state_reason === 'not_planned') continue; // closed as out-of-fleet; re-adding it is the standing fix
183	    if (prior) {
184	      await gh(`/repos/${home}/issues/${prior.number}`, {
185	        method: 'PATCH', body: { state: 'open', body: driftBody(fullName, verdict, staleDays) },
186	      });
187	      await gh(`/repos/${home}/issues/${prior.number}/comments`, {
188	        method: 'POST', body: { body: `Reopened by the sweep: \`${fullName}\` has fallen behind again (${verdict.state}). ${verdict.detail}.` },
189	      });
190	      actions.push(`reopened #${prior.number} (${fullName}: ${verdict.state})`);
191	    } else {
192	      const { status, json } = await gh(`/repos/${home}/issues`, {
193	        method: 'POST',
194	        body: { title, body: driftBody(fullName, verdict, staleDays), labels: [LABEL] },
195	      });
196	      if (status !== 201) throw new Error(`creating drift issue for ${fullName} returned ${status}`);
197	      actions.push(`opened #${json.number} (${fullName}: ${verdict.state})`);
198	    }
199	  }
200	
201	  for (const [title, issue] of open) {
202	    const m = TITLE_RE.exec(title);
203	    if (!m) continue;
204	    const fullName = m[1].toLowerCase();
205	    if (wanted.has(fullName)) continue;
206	    let reason = null; let note = null;
207	    if (healthySet.has(fullName)) {
208	      reason = 'completed'; note = 'is up to date with canon again';
209	    } else if (dormantSet.has(fullName)) {
210	      // `not planned`, not `completed`: the drift was never fixed, the repo was
211	      // taken out of the race. Closing it `completed` would claim a repair nobody
212	      // made, and leaving it open would be the nagging dormancy exists to stop.
213	      reason = 'not_planned'; note = 'has declared itself dormant — it is out of the recurring work, so the sweep no longer measures it';
214	    } else if (goneSet.has(fullName)) {
215	      reason = 'not_planned'; note = 'is no longer a covered member of the fleet (excluded, deleted, archived, or uncovered)';
216	    }
217	    if (!reason) continue; // classified UNKNOWN this run — say nothing rather than guess
218	    await gh(`/repos/${home}/issues/${issue.number}/comments`, {
219	      method: 'POST', body: { body: `Closed by the sweep: \`${m[1]}\` ${note}.` },
220	    });
221	    await gh(`/repos/${home}/issues/${issue.number}`, {
222	      method: 'PATCH', body: { state: 'closed', state_reason: reason },
223	    });
224	    actions.push(`closed #${issue.number} (${m[1]}: ${note})`);
225	  }
226	  return actions;
227	}
228	
229	// --- per-member probe ---------------------------------------------------------
230	
231	// Three reads per member: the declaration (content, not just existence — the stamp is
232	// in it), the scheduler workflow's presence, and canon's view of the stamped ref.
233	// Throws on anything indeterminate; the caller turns that into UNKNOWN. Exported so
234	// the "a dormant member is never probed further" contract is testable without a
235	// network — it is a decision, not plumbing.
236	export async function probe(gh, fullName, { canonRepo, canonBranch }) {
237	  const cfg = await readDeclaration(gh, fullName);
238	  if (cfg === null) return null; // uncovered — the census's business, not this sweep's
239	  // A DORMANT member is not measured. Its scheduler stops before it evaluates
240	  // anything, so nothing there baselines and the mount falls behind BY DESIGN —
241	  // every question below would answer "behind" for a repo that was told to stop
242	  // keeping up. Reporting that is not an outside look, it is nagging a repo for
243	  // obeying its own declaration. Detected here, before the stamp is even read.
244	  if (isDormant(cfg)) return { dormant: true };
245	  const stampedRef = cfg?.claudinite?.ref ?? null;
246	
247	  const wf = await gh(`/repos/${fullName}/contents/${SCHEDULER}`);
248	  if (wf.status !== 200 && wf.status !== 404) throw new Error(`${SCHEDULER} check returned ${wf.status}`);
249	  const hasScheduler = wf.status === 200;
250	
251	  let compare = null;
252	  if (stampedRef) {
253	    // per_page=1 because the commit list is irrelevant here — only the counts, the
254	    // status, and the base commit's date are read, and a wide-open compare over a
255	    // fortnight of canon is a needlessly large payload.
256	    const c = await gh(`/repos/${canonRepo}/compare/${stampedRef}...${canonBranch}?per_page=1`);
257	    if (c.status === 404) compare = null; // not a canon commit — classify(), not an error
258	    else if (c.status !== 200 || !c.json) throw new Error(`comparing ${stampedRef} against ${canonRepo}@${canonBranch} returned ${c.status}`);
259	    else {
260	      compare = {
261	        status: c.json.status,
262	        aheadBy: c.json.ahead_by ?? 0,
263	        baseDateMs: Date.parse(c.json.base_commit?.commit?.committer?.date ?? ''),
264	      };
265	      if (!Number.isFinite(compare.baseDateMs)) throw new Error(`canon returned no usable date for ${stampedRef}`);
266	    }
267	  }
268	  return { stampedRef, hasScheduler, compare };
269	}
270	
271	// --- main ---------------------------------------------------------------------
272	
273	export async function main() {
274	  const token = process.env.FLEET_GITHUB_TOKEN;
275	  const home = process.env.GITHUB_REPOSITORY;
276	  if (!token) {
277	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
278	      + '(this account, ALL repositories, Metadata read, Contents read + Issues read/write) — '
279	      + 'the default GITHUB_TOKEN sees only this repo and cannot sweep the fleet.');
280	  }
281	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
282	  const gh = makeGh(token);
283	
284	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
285	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
286	    throw new Error(`the sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
287	  }
288	  let cfg;
289	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
290	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
291	  }
292	  const { owner, exclude, canonRepo, staleDays } = parseSheepdogConfig(cfg, home);
293	
294	  // Canon's default branch is what "on trunk" means; read it rather than assuming main.
295	  const canonRes = await gh(`/repos/${canonRepo}`);
296	  if (canonRes.status !== 200 || !canonRes.json?.default_branch) {
297	    throw new Error(`canon repo ${canonRepo} is unreadable (status ${canonRes.status}) — set canonRepo on the sheepdog pack entry's config if it is not ${owner}/Claudinite`);
298	  }
299	  const canonBranch = canonRes.json.default_branch;
300	
301	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
302	    .filter((r) => r.owner.login.toLowerCase() === owner);
303	  if (mine.length === 0) {
304	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope; `
305	      + 'refusing to run a sweep that would close every drift issue as stale');
306	  }
307	
308	  const unhealthy = []; const healthy = []; const gone = []; const dormant = []; const unknown = [];
309	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
310	    const fullName = r.full_name.toLowerCase();
311	    if (fullName === home.toLowerCase()) continue;         // the enforcer is swept by its own scheduler
312	    if (fullName === canonRepo.toLowerCase()) continue;    // canon has no vendored mount to be stale
313	    if (r.archived || r.fork || exclude.has(fullName)) { gone.push(fullName); continue; }
314	    let p;
315	    try {
316	      p = await probe(gh, r.full_name, { canonRepo, canonBranch });
317	    } catch (e) {
318	      unknown.push(`${r.full_name} — ${e.message}`);
319	      continue;
320	    }
321	    if (p === null) { gone.push(fullName); continue; }     // uncovered: the census owns it
322	    // Dormant by its own declaration: out of the sweep, and counted SEPARATELY from
323	    // `gone` so the summary says how much of the fleet is asleep rather than hiding
324	    // it inside "out of scope". An open drift issue on it closes with its own note.
325	    if (p.dormant) { dormant.push(fullName); continue; }
326	    const verdict = classifyFreshness({ ...p, nowMs: Date.now(), staleDays });
327	    if (verdict.state === FRESH) healthy.push(fullName);
328	    else unhealthy.push({ fullName, ...verdict });
329	  }
330	
331	  await ensureLabel(gh, home, LABEL, { color: 'D93F0B', description: 'Covered member whose Claudinite mount has fallen behind canon' });
332	  const actions = await convergeDrift(gh, home, {
333	    unhealthy, healthySet: new Set(healthy), goneSet: new Set(gone), dormantSet: new Set(dormant), staleDays,
334	  });
335	
336	  const summary = [
337	    `# Fleet freshness sweep — ${owner} (window: ${staleDays} days, canon: ${canonRepo}@${canonBranch})`,
338	    '',
339	    '| fresh | behind | no scheduler | no stamp | off trunk | dormant | out of scope | unknown |',
340	    '| --- | --- | --- | --- | --- | --- | --- | --- |',
341	    `| ${healthy.length} | ${unhealthy.filter((u) => u.state === 'behind').length} | `
342	      + `${unhealthy.filter((u) => u.state === 'no-scheduler').length} | `
343	      + `${unhealthy.filter((u) => u.state === 'no-stamp').length} | `
344	      + `${unhealthy.filter((u) => u.state === 'ref-not-on-trunk').length} | ${dormant.length} | ${gone.length} | ${unknown.length} |`,
345	    '',
346	    unhealthy.length
347	      ? `**Behind (drift issue open):**\n${unhealthy.map((u) => `- \`${u.fullName}\` — **${u.state}**: ${u.detail}`).join('\n')}`
348	      : '**Every covered member is up to date 🎉**',
349	    dormant.length ? `**Dormant (self-declared, not measured):** ${dormant.join(', ')}` : '',
350	    unknown.length ? `**UNKNOWN (probe errored — fix the token/scope):** ${unknown.join('; ')}` : '',
351	    actions.length ? `**Issue actions:** ${actions.join('; ')}` : '**Issue actions:** none (converged)',
352	  ].filter(Boolean).join('\n');
353	
354	  console.log(summary);
355	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
356	
357	  if (unknown.length) {
358	    throw new Error(`${unknown.length} repo(s) could not be probed — unknown is not behind, `
359	      + 'no drift issues were opened for them, and this run fails so the cause is escalated');
360	  }
361	}
362	
363	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
364	if (isMain) {
365	  main().catch((e) => { console.error(`fleet-freshness sweep failed: ${e.message}`); process.exit(1); });
366	}
