1	#!/usr/bin/env node
2	// The sheepdog pack's fleet-USAGE sweep — the third cross-repo reach the pack adds,
3	// alongside the coverage census and the freshness sweep. Run by this pack's
4	// `fleet-usage` scheduled task (tasks/fleet-usage/), whose worker calls `main()`
5	// below as the task's `prework`, Action-side inside the enforcer repo's
6	// scheduler workflow where FLEET_GITHUB_TOKEN is reachable. Still runnable by hand
7	// (`node aggregate-fleet-usage.mjs`) via the CLI guard at the foot.
8	//
9	// WHY IT EXISTS. Each member folds ITS OWN skill-usage aggregate (the
10	// grow_with_claudinite pack's usage-fold task). A member can therefore answer "does
11	// this skill ever load HERE" — and cannot answer the question the promotion ladder
12	// actually asks, which is whether a skill earns its place ACROSS THE FLEET. A skill
13	// that never loads in one repo may simply not be that repo's subject; a skill that
14	// never loads in any of them is mis-described or should not be gated at all. Only
15	// something looking at every member at once can tell those apart, and looking at
16	// every member is the sheepdog's whole job.
17	//
18	// STATELESS FULL RECOMPUTE. Read each member's usage file at its default branch and
19	// rebuild the fleet file as a pure function of those inputs. Idempotent by
20	// definition, and it self-heals any past error — at this cardinality (repos ×
21	// skills × weeks, all small) there is nothing to optimize away.
22	//
23	// COVERAGE IS EXPLICIT. A member with no usage file (not folding yet) or an
24	// unreadable one is LISTED as absent, census-style, never silently skipped. A
25	// denominator with an invisible hole in it is worse than no denominator. A member
26	// that declares itself DORMANT is out of the denominator entirely — and listed
27	// under its own heading, because "not in the race" and "should be folding and
28	// isn't" are different facts and only one of them is a problem.
29	//
30	// The canon knows mechanisms, never repos: no member is named anywhere here. The
31	// member set is enumerated at runtime from the enforcer's own sheepdog config,
32	// exactly as the census and the freshness sweep enumerate it.
33	//
34	// Dependency-free (global fetch, Node 20+); read-only toward every member — the only
35	// thing it writes is the enforcer repo's own aggregate, and that is delivered by the
36	// worker, not here.
37	//
38	// It lives IN its task's folder because nothing else uses it. What IS shared with
39	// the other two sweeps sits at the pack root: the cross-repo REST primitives
40	// (fleet-api.mjs) and the config reader (fleet-config.mjs).
41	
42	import { pathToFileURL } from 'node:url';
43	import { makeGh, paged, readDeclaration, isDormant, DECLARATION } from '../../fleet-api.mjs';
44	import { parseSheepdogConfig } from '../../fleet-config.mjs';
45	export const MEMBER_USAGE_PATH = '.claudinite/local/usage.GENERATED.json';
46	export const FLEET_USAGE_PATH = 'usage-fleet.GENERATED.json';
47	export const FLEET_VERSION = 1;
48	
49	// The sampling population, stated in the file itself. This must not read as a
50	// census: a session whose container was reclaimed, or that crashed, never captured
51	// and is invisible to every number here.
52	export const SAMPLING_NOTE = 'Captured sessions only — sessions that merged, plus sessions that ended '
53	  + 'cleanly enough for the SessionEnd capture to fire. Reclaimed containers and crashes are invisible '
54	  + 'here, so these are SAMPLE counts, not a census of all work. The check counts are narrower still: '
55	  + 'they are what a session SAW. A CI run counts when the session pulled its job log in — which is '
56	  + 'what "the agent was in the loop on it" means — and a nightly or post-merge run nobody looked at '
57	  + 'does not, because nothing was corrected. CI can only see a run that PRINTED something, so its '
58	  + 'share is carried separately as ciRuns/ciFailures. Every check number is a floor on activations, '
59	  + 'never an over-count. The `tasks` rows are the ONE exception to all of the above: they come from '
60	  + "each member's scheduler run records rather than from a captured session, so they are a census of "
61	  + 'scheduled work — every due task of every run, whether or not any session was ever captured — '
62	  + 'bounded only by how far back that member has been folding them.';
63	
64	// --- the pure aggregation -----------------------------------------------------
65	
66	const sortKeys = (obj) => Object.fromEntries(Object.keys(obj).sort().map((k) => [k, obj[k]]));
67	
68	// Build the fleet file from `members` — `[{ repo, usage }]`, `usage` being that
69	// member's parsed aggregate — plus `absent`, the members that had none.
70	//
71	// GRAIN: full (week × repo × skill) for history, plus each member's current day
72	// window verbatim for the fast view. Nothing is pre-summed: every coarser view
73	// (a skill fleet-wide, a repo over time, this week across the fleet) stays derivable
74	// from this file, and a summary that threw away the grain would not.
75	export function aggregate({ members, absent = [], dormant = [], generatedAt }) {
76	  const weeks = {};
77	  const days = {};
78	  const repos = {};
79	
80	  for (const { repo, usage } of members) {
81	    days[repo] = sortKeys(usage?.days ?? {});
82	    repos[repo] = {
83	      foldedThrough: usage?.foldedThrough ?? null,
84	      weeks: Object.keys(usage?.weeks ?? {}).length,
85	    };
86	    for (const [week, row] of Object.entries(usage?.weeks ?? {})) {
87	      ((weeks[week] ??= {})[repo] = {
88	        days: row.days ?? 0,
89	        captures: row.captures ?? 0,
90	        merges: row.merges ?? 0,
91	        sessionDays: row.sessionDays ?? 0,
92	        userMessages: row.userMessages ?? 0,
93	        userCommands: row.userCommands ?? 0,
94	        skillLoads: sortKeys(row.skillLoads ?? {}),
95	        // The conformance checks, at the same grain and for the same reason as the
96	        // skill loads: whether a rule earns its place is a FLEET question. A rule
97	        // that never fires in one repo may just not be that repo's subject; a rule
98	        // that never fires in ANY of them is mis-described or worthless — and a rule
99	        // that keeps firing everywhere is the corpus's best-performing guard, which
100	        // only a view across every member can tell apart. Defaulted, not required:
101	        // a member still on an older fold carries no `checks` key, and it must land
102	        // in the file as an empty row rather than an exception.
103	        checks: sortKeys(row.checks ?? {}),
104	        checkFindings: sortKeys(row.checkFindings ?? {}),
105	        // What each member's SCHEDULER did, per task: agent runs, deterministic
106	        // preprocessing-only runs, precondition skips, failures, deferrals. Carried
107	        // at the same week × repo × task grain and defaulted the same way, but drawn
108	        // from a different population and answering a different question — this is
109	        // the fleet's view of whether a scheduled task is doing anything at all. A
110	        // task that skips in every member every day is a precondition that never
111	        // fires; one that fails across members is broken machinery, not a bad night.
112	        tasks: sortKeys(row.tasks ?? {}),
113	      });
114	    }
115	  }
116	
117	  return {
118	    version: FLEET_VERSION,
119	    generatedAt,
120	    _note: SAMPLING_NOTE,
121	    coverage: {
122	      folding: Object.keys(repos).sort(),
123	      absent: [...absent].sort(),
124	      // Dormant members are OUT of the denominator, and named rather than dropped.
125	      // They are not an absence to chase — nobody is working there, so a skill that
126	      // never loads there says nothing about whether it earns its place — but a
127	      // reader comparing this file against the fleet's repo count needs to see where
128	      // the difference went. Absent means "should be folding and isn't"; dormant
129	      // means "not in the race at all".
130	      dormant: [...dormant].sort(),
131	    },
132	    repos: sortKeys(repos),
133	    days: sortKeys(days),
134	    weeks: sortKeys(Object.fromEntries(Object.entries(weeks).map(([w, byRepo]) => [w, sortKeys(byRepo)]))),
135	  };
136	}
137	
138	// --- the fleet read -----------------------------------------------------------
139	
140	// One member's usage file at its default branch, or null when it has none. A
141	// non-200 that is not a 404, or an unparsable body, THROWS — the caller records it
142	// as an absence with a reason rather than treating "I could not read it" as "it has
143	// nothing".
144	async function readUsage(gh, fullName, path = MEMBER_USAGE_PATH) {
145	  const res = await gh(`/repos/${fullName}/contents/${path}`);
146	  if (res.status === 404) return null;
147	  if (res.status !== 200 || !res.json?.content) {
148	    throw new Error(`reading ${path} returned ${res.status}`);
149	  }
150	  try {
151	    return JSON.parse(Buffer.from(res.json.content, 'base64').toString('utf8'));
152	  } catch (e) {
153	    throw new Error(`unparsable ${path}: ${e.message}`);
154	  }
155	}
156	
157	// Exported so the fleet-usage task's worker can invoke the sweep in-process; the CLI
158	// guard below keeps the standalone run. Returns the built file — the worker owns
159	// delivering it, so this stays a pure "read the fleet, build the object" pass.
160	export async function main({ now = new Date() } = {}) {
161	  const token = process.env.FLEET_GITHUB_TOKEN;
162	  const home = process.env.GITHUB_REPOSITORY;
163	  if (!token) {
164	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
165	      + '(this account, ALL repositories, Metadata read, Contents read) — the default GITHUB_TOKEN '
166	      + 'sees only this repo and cannot read the fleet.');
167	  }
168	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
169	  const gh = makeGh(token);
170	
171	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
172	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
173	    throw new Error(`the sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
174	  }
175	  let cfg;
176	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
177	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
178	  }
179	  const { owner, exclude } = parseSheepdogConfig(cfg, home);
180	
181	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
182	    .filter((r) => r.owner.login.toLowerCase() === owner);
183	  if (mine.length === 0) {
184	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope; `
185	      + 'refusing to publish a fleet aggregate that would report the whole fleet as absent');
186	  }
187	
188	  const members = [];
189	  const absent = [];
190	  const dormant = [];
191	  for (const r of mine.sort((a, b) => a.full_name.localeCompare(b.full_name))) {
192	    const fullName = r.full_name;
193	    const key = fullName.toLowerCase();
194	    if (r.archived || r.fork || exclude.has(key)) continue;
195	    // Only COVERED repos are members. An uncovered repo is the census's subject, not
196	    // this sweep's — reporting it as an absent member would file the same fact twice.
197	    // The declaration is read rather than merely counted because dormancy is inside
198	    // it, and the same read answers both questions.
199	    let decl;
200	    try { decl = await readDeclaration(gh, fullName); } catch (e) {
201	      absent.push(`${fullName} (coverage check failed: ${e.message})`);
202	      continue;
203	    }
204	    if (decl === null) continue;
205	    // A dormant member is out of the DENOMINATOR, not an absence: nobody is working
206	    // there, so "this skill never loaded" is a fact about the silence, not about the
207	    // skill, and averaging it in would drag every fleet-wide number toward zero as
208	    // the fleet accumulates finished projects.
209	    if (isDormant(decl)) { dormant.push(fullName); continue; }
210	    try {
211	      const usage = await readUsage(gh, fullName);
212	      if (usage === null) absent.push(`${fullName} (no ${MEMBER_USAGE_PATH} — not folding yet)`);
213	      else members.push({ repo: fullName, usage });
214	    } catch (e) {
215	      absent.push(`${fullName} (${e.message})`);
216	    }
217	  }
218	
219	  return aggregate({ members, absent, dormant, generatedAt: now.toISOString().slice(0, 10) });
220	}
221	
222	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
223	if (isMain) {
224	  main()
225	    .then((file) => console.log(JSON.stringify(file, null, 2)))
