1	// The sheepdog census's cross-repo GitHub REST client. Dependency-free (global
2	// fetch, Node 20+). This is the ONE place a Claudinite process talks GitHub over
3	// raw REST with a token, and it is deliberately confined to the census — the
4	// account-spanning coverage audit that must enumerate EVERY repo the owner owns
5	// (`/user/repos`), which a session-scoped connection structurally cannot see. The
6	// census runs Action-side as the fleet-census task's preprocessing, with a
7	// fine-grained PAT; nothing in the daily-maintenance process imports this (that
8	// process is MCP-native and carries no REST client). It knows nothing about any
9	// specific pack: it is the generic "talk to many repos" layer, no more.
10	
11	import { isDormant } from '../../engine/checks/helpers/repo-context.mjs';
12	
13	const API = 'https://api.github.com';
14	
15	// The tracked declaration every member carries — the file the sweeps read a member's
16	// membership, stamp and dormancy out of. Named once here because all three sweeps
17	// name it.
18	export const DECLARATION = '.claudinite-checks.json';
19	
20	// Dormancy, re-exported from the engine rather than re-tested here. A member declares
21	// itself dormant in its OWN declaration, and the test has to be the same one that
22	// member's scheduler used to stop itself — a sweep with its own private notion of
23	// dormancy would nag exactly the repos that had already opted out, which is the whole
24	// failure this exists to prevent.
25	export { isDormant };
26	
27	export function makeGh(token) {
28	  return async function gh(path, { method = 'GET', body } = {}) {
29	    const res = await fetch(`${API}${path}`, {
30	      method,
31	      headers: {
32	        Authorization: `Bearer ${token}`,
33	        Accept: 'application/vnd.github+json',
34	        'X-GitHub-Api-Version': '2022-11-28',
35	        ...(body ? { 'Content-Type': 'application/json' } : {}),
36	      },
37	      body: body ? JSON.stringify(body) : undefined,
38	    });
39	    const text = await res.text();
40	    let json = null;
41	    try { json = text ? JSON.parse(text) : null; } catch { /* non-JSON body */ }
42	    return { status: res.status, json };
43	  };
44	}
45	
46	export async function paged(gh, path) {
47	  const sep = path.includes('?') ? '&' : '?';
48	  const all = [];
49	  for (let page = 1; ; page += 1) {
50	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
51	    if (status !== 200 || !Array.isArray(json)) {
52	      throw new Error(`GET ${path} page ${page} failed with status ${status}`);
53	    }
54	    all.push(...json);
55	    if (json.length < 100) return all;
56	  }
57	}
58	
59	// --- the enforcer repo's own issue surface -----------------------------------
60	// Both sweeps this pack runs (coverage and freshness) converge a labelled issue
61	// per finding IN THE ENFORCER REPO. The label ensure and the labelled-issue read
62	// are identical between them — only the open/close POLICY differs, and that stays
63	// in each sweep, where its semantics are legible. These two are the shared floor.
64	
65	// Idempotent: 422 is "already exists", which is the state we wanted.
66	export async function ensureLabel(gh, repo, name, { color, description }) {
67	  const { status } = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
68	  if (status !== 201 && status !== 422) throw new Error(`creating label ${name} returned ${status}`);
69	}
70	
71	// Every issue ever carrying the label, open and closed, PRs filtered out — a
72	// sweep needs the closed ones to tell "converged" from "never opened", and to
73	// honour a close the owner made deliberately.
74	export async function labeledIssues(gh, repo, label) {
75	  const all = (await paged(gh, `/repos/${repo}/issues?labels=${label}&state=all`)).filter((i) => !i.pull_request);
76	  return { open: all.filter((i) => i.state === 'open'), closed: all.filter((i) => i.state === 'closed') };
77	}
78	
79	// 200 → true, 404 → false, anything else → error (the caller decides what an
80	// indeterminate result means).
81	export async function fileExists(gh, fullName, path) {
82	  const { status } = await gh(`/repos/${fullName}/contents/${path}`);
83	  if (status === 200) return true;
84	  if (status === 404) return false;
85	  throw new Error(`marker check ${fullName}:${path} returned ${status}`);
86	}
87	
88	// One repo's parsed declaration, or null when it has none (uncovered). Anything
89	// else — an unreadable response, an unparsable body — THROWS, because a sweep that
90	// cannot read a member's declaration knows nothing about it, and "I could not read
91	// it" must never quietly become "it says nothing". Shared by the sweeps that need
92	// what is INSIDE the file (the stamp, the dormancy flag) rather than only that it
93	// exists.
94	export async function readDeclaration(gh, fullName, path = DECLARATION) {
95	  const res = await gh(`/repos/${fullName}/contents/${path}`);
96	  if (res.status === 404) return null;
97	  if (res.status !== 200 || !res.json?.content) throw new Error(`${path} returned ${res.status}`);
98	  try {
99	    return JSON.parse(Buffer.from(res.json.content, 'base64').toString('utf8'));
100	  } catch (e) {
101	    throw new Error(`unparsable ${path}: ${e.message}`);
102	  }
103	}
104	
105	// Does this repo mount Claudinite? (Method B sync hook / legacy gitkeep / Method A
106	// submodule.) The structural "is this a covered member" test, shared by the planner
107	// (which repos to plan over) and the census (which repos are uncovered).
108	export async function isCovered(gh, fullName) {
109	  // The tracked declaration file is THE membership signal — the one file every
110	  // member carries whatever its mount shape (the engine can't run without it,
111	  // and baselining backfills it nightly), and the only shape the planner can
112	  // plan for at all (activePacks is read from it). A mount marker WITHOUT a
113	  // declaration is a half-adoption that must classify as uncovered — the census
114	  // then opens an adoption issue and it heals loudly, instead of rotting as a
115	  // "covered" repo no task ever runs on. (vendoring/DESIGN.md)
116	  return fileExists(gh, fullName, '.claudinite-checks.json');
117	}
118

